let chatInput = $json.chatInput || $input.first().json.body.chatInput;
let sessionId = $json.sessionId || $input.first().json.body.sessionId;

return [{ json: { chatInput, sessionId } }];

// Agent-Tool-Input lesen
const inp = $input.first().json;
const code = inp.query || inp.input || inp.code || inp.programCode || '';

const VALID_COMMANDS = ['GET','GETNOT','DUP','NOT','AND','OR','XOR','MOV','CMOV','SET','CSET','CINC','CDEC','CMP','GT','LE'];

const STACK_EFFECTS = {
  'GET':   { pop: 0, push: 1 }, 'GETNOT': { pop: 0, push: 1 },
  'NOT': { pop: 1, push: 1 },
  'AND':   { pop: 2, push: 1 }, 'OR': { pop: 2, push: 1 }, 'XOR': { pop: 2, push: 1 },
  'MOV':   { pop: 1, push: 0 }, 'CMOV': { pop: 1, push: 0 },
  'SET':   { pop: 0, push: 0 }, 'CSET': { pop: 1, push: 0 },
  'CINC':  { pop: 1, push: 0 }, 'CDEC': { pop: 1, push: 0 },
  'CMP':   { pop: 0, push: 1 }, 'GT': { pop: 0, push: 1 }, 'LE': { pop: 0, push: 1 }
};

const LIMITS = { 'I': 64, 'O': 64, 'M': 1024, 'T': 128, 'C': 128 };

// Erlaubte Operand-Typen pro Befehl (erster Operand nach dem Befehlsnamen)
const ALLOWED_SUBJECTS = {
  'GET':   ['I','O','M','T'],      // GET C existiert NICHT
  'GETNOT':['I','O','M','T'],      // GETNOT C existiert NICHT
  'MOV':   ['O','M'],              // MOV C existiert NICHT
  'CMOV':  ['O','M'],              // CMOV C existiert NICHT
  'SET':   ['T','C'],              // SET I/O/M existiert NICHT
  'CSET':  ['T','C'],              // CSET I/O/M existiert NICHT
  'CINC':  ['C'],                  // nur Counter
  'CDEC':  ['C'],                  // nur Counter
  'CMP':   ['C'],                  // nur Counter
  'GT':    ['C'],                  // nur Counter
  'LE':    ['C'],                  // nur Counter
};

const lines = code.split('\n').map(l => l.trim()).filter(l => l.length > 0);
const errors = [];
const trace = [];
let depth = 0;
let lineNum = 0;

for (const line of lines) {
  lineNum++;
  if (line.startsWith('#')) { trace.push({ l: lineNum, i: line, d: depth, comment: true }); continue; }
  const parts = line.split(/\s+/);
  const cmd = parts[0].toUpperCase();

  if (!VALID_COMMANDS.includes(cmd)) {
    errors.push(`Zeile ${lineNum}: Unbekannter Befehl '${cmd}'`);
    continue;
  }

  // DUP-Sonderbehandlung: DUP ohne Arg = Value 2, Loop laeuft k-1 mal
  if (cmd === 'DUP') {
    const k = parts.length >= 2 ? parseInt(parts[1]) : 2;
    if (isNaN(k) || k < 0) {
      errors.push(`Zeile ${lineNum}: DUP-Argument '${parts[1]}' ungueltig`);
      continue;
    }
    if (k === 1) errors.push(`Zeile ${lineNum}: FEHLER: 'DUP 1' ist ein NOP (0 Pushes) — Stack unveraendert! Verwende DUP ohne Argument.`);
    if (k > 1 && depth < 1) errors.push(`Zeile ${lineNum}: Stack-Unterlauf bei 'DUP' (braucht 1, hat ${depth})`);
    const beforeDup = depth;
    const pushCount = Math.max(0, k - 1);
    depth += pushCount;
    trace.push({ l: lineNum, i: line, before: beforeDup, after: depth });
    continue;
  }

  const fx = STACK_EFFECTS[cmd];
  const before = depth;
  const minReq = fx.needsMin || fx.pop;

  if (depth < minReq)
    errors.push(`Zeile ${lineNum}: Stack-Unterlauf bei '${cmd}' (braucht ${minReq}, hat ${depth})`);

  // Operand-Typ und Adresse pruefen (fuer Befehle mit Subjekt + Adresse)
  if (ALLOWED_SUBJECTS[cmd] && parts.length >= 2) {
    const subj = parts[1].toUpperCase();
    const allowed = ALLOWED_SUBJECTS[cmd];

    // Sonderfall GET/GETNOT: GET 0 / GET 1 sind Konstanten (kein Subjekt)
    const isConstant = (cmd === 'GET') && (parts[1] === '0' || parts[1] === '1');

    if (!isConstant) {
      if (!allowed.includes(subj)) {
        errors.push(`Zeile ${lineNum}: '${cmd} ${subj}' ist ungueltig — ${cmd} erlaubt nur: ${allowed.join('/')}`);
      } else if (parts.length >= 3) {
        const addr = parseInt(parts[2]);
        if (LIMITS[subj] !== undefined && (isNaN(addr) || addr < 0 || addr >= LIMITS[subj]))
          errors.push(`Zeile ${lineNum}: Adresse ${parts[2]} ungueltig fuer ${subj} (erlaubt: 0-${LIMITS[subj]-1})`);
      }
    }
  }

  depth = Math.max(0, depth - fx.pop + fx.push);
  trace.push({ l: lineNum, i: line, before, after: depth });
}

if (depth !== 0) errors.push(`Stack nicht leer am Ende: Tiefe=${depth}`);

const valid = errors.length === 0;
let result = `Validierung: ${valid ? 'GUELTIG' : 'FEHLERHAFT — DEPLOY VERBOTEN, ERST CODE KORRIGIEREN!'}\n`;
if (!valid) { result += 'Fehler:\n' + errors.map(e => `- ${e}`).join('\n') + '\n'; }
result += 'Stack-Trace:\n' + trace.filter(t => !t.comment).map(t => `  ${t.l}: [${t.before}] ${t.i} [${t.after}]`).join('\n');
return result;

// Holt das aktuell in der Steuerung geladene Programm von der Desktop App API
try {
  const response = await $http.request({
    method: 'GET',
    url: 'http://localhost:5555/api/program',
    returnFullResponse: true
  });

  const body = response.body;

  // Body als String (JSON-Text)
  if (typeof body === 'string') {
    try {
      const parsed = JSON.parse(body);
      if (parsed.programCode) return `Programm von Steuerung geladen (${parsed.sourceLines || '?'} Zeilen):\n\n${parsed.programCode}`;
      if (parsed.source) return `Programm von Steuerung geladen:\n\n${parsed.source}`;
      return body;
    } catch {
      return body;
    }
  }

  // Body als Objekt (n8n hat bereits geparst)
  if (body && body.programCode) {
    return `Programm von Steuerung geladen (${body.sourceLines || '?'} Zeilen):\n\n${body.programCode}`;
  }
  if (body && body.source) {
    return `Programm von Steuerung geladen:\n\n${body.source}`;
  }

  return `Steuerung erreichbar, aber kein Programm geladen. Antwort: ${JSON.stringify(body)}`;

} catch (e) {
  return `FEHLER: Steuerung nicht erreichbar. Ist die FPC Desktop App gestartet? Details: ${e.message}`;
}

// TestRunner v2 - robust HTTP + diagnostic
const REST = 'http://localhost:5555';

async function getJson(path) {
  try {
    const r = await $http.request({ method: 'GET', url: REST + path, returnFullResponse: true });
    let b = (r && typeof r === 'object' && 'body' in r) ? r.body : r;
    if (typeof b === 'string') { try { b = JSON.parse(b); } catch {} }
    return b;
  } catch (e) { return { _httpError: e.message, _at: 'GET ' + path }; }
}

async function postJson(path, body) {
  try {
    const opts = { method: 'POST', url: REST + path, returnFullResponse: true };
    if (body !== undefined) {
      opts.headers = { 'Content-Type': 'application/json' };
      opts.body = typeof body === 'string' ? body : JSON.stringify(body);
    }
    const r = await $http.request(opts);
    let b = (r && typeof r === 'object' && 'body' in r) ? r.body : r;
    if (typeof b === 'string') { try { b = JSON.parse(b); } catch {} }
    return b;
  } catch (e) { return { _httpError: e.message, _at: 'POST ' + path }; }
}

async function getOutputs() {
  const r = await getJson('/api/outputs');
  const arr = Array(20).fill(0);
  if (r && Array.isArray(r.outputs)) {
    for (const o of r.outputs) if (o.index < arr.length) arr[o.index] = o.value ? 1 : 0;
    return { arr, ok: true };
  }
  return { arr, ok: false, raw: r };
}

async function getInputs() {
  const r = await getJson('/api/inputs');
  const arr = Array(20).fill(0);
  if (r && Array.isArray(r.inputs)) {
    for (const o of r.inputs) if (o.index < arr.length) arr[o.index] = o.value ? 1 : 0;
    return arr;
  }
  return arr;
}

async function setInput(idx, val) {
  const inputs = await getInputs();
  const target = val ? 1 : 0;
  if (inputs[idx] !== target) await postJson('/api/inputs/' + idx + '/toggle');
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// === main ===
const inp = $input.first().json;
let params = inp;
if (inp && (inp.query || inp.input)) {
  const raw = inp.query || inp.input;
  if (typeof raw === 'string') {
    try { params = JSON.parse(raw); } catch {
      return 'FEHLER: Input konnte nicht als JSON geparst werden. Erwartet: { cycleLengthMs, samples:[...], notausTest:{...} }';
    }
  } else params = raw;
}

// Diagnostic: first HTTP call shape
const _diag = await getJson('/api/outputs');
const _diagSummary = {
  ok: !!(_diag && Array.isArray(_diag.outputs)),
  typeof: typeof _diag,
  snippet: JSON.stringify(_diag).slice(0, 300)
};

const samples = params.samples || [];
const notausTest = params.notausTest;
const resetInputs = params.resetInputs || [];
const stabiliseMs = params.stabiliseMs ?? 200;

// Phase 0: stop, reset inputs, start
await postJson('/api/stop');
for (const ri of resetInputs) await setInput(ri.index, ri.value);
await postJson('/api/start');
const startTime = Date.now();

// Phase 1: cycle samples
const sorted = [...samples].sort((a, b) => a.tMs - b.tMs);
const results = [];
for (const s of sorted) {
  const wait = s.tMs - (Date.now() - startTime);
  if (wait > 0) await sleep(wait);
  const { arr: actual, ok } = await getOutputs();
  const expected = s.outputs || s.expected || [];
  const diffs = [];
  for (let i = 0; i < expected.length; i++) {
    if (actual[i] !== expected[i]) diffs.push({ O: i, expected: expected[i], actual: actual[i] });
  }
  results.push({
    label: s.label || ('t=' + s.tMs + 'ms'),
    tMs: s.tMs,
    actualElapsedMs: Date.now() - startTime,
    expected,
    actual: actual.slice(0, Math.max(expected.length, 3)),
    httpOk: ok,
    pass: ok && diffs.length === 0,
    diffs
  });
}

// Phase 2: NOTAUS
let notausResult = null;
if (notausTest) {
  await postJson('/api/stop');
  const idx = notausTest.index ?? 0;
  await setInput(idx, true);
  await postJson('/api/start');
  await sleep(stabiliseMs + 300);
  const { arr: actual, ok } = await getOutputs();
  const expected = notausTest.expected || [];
  const diffs = [];
  for (let i = 0; i < expected.length; i++) {
    if (actual[i] !== expected[i]) diffs.push({ O: i, expected: expected[i], actual: actual[i] });
  }
  notausResult = {
    label: notausTest.label || 'NOTAUS',
    expected,
    actual: actual.slice(0, Math.max(expected.length, 3)),
    httpOk: ok,
    pass: ok && diffs.length === 0,
    diffs
  };
  await postJson('/api/stop');
  await setInput(idx, false);
}

const passCycle = results.filter((r) => r.pass).length;
const total = results.length + (notausTest ? 1 : 0);
const passed = (passCycle === results.length) && (notausTest ? notausResult.pass : true);

return JSON.stringify({
  passed,
  summary: passed
    ? ('ALLE ' + total + ' TESTS BESTANDEN')
    : ((total - passCycle - (notausResult && notausResult.pass ? 1 : 0)) + ' von ' + total + ' FEHLGESCHLAGEN - CODE KORRIGIEREN UND NEU DEPLOYEN+TESTEN'),
  cycleResults: results,
  notausResult,
  _diagnostic: _diagSummary
}, null, 2);
